#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort (stable on equal magnitudes via index tie-breaker)
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase & 1U; // even phase: 0, odd phase: 1

        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i + 1 < static_cast<std::ptrdiff_t>(n);
             i += 2) {
            const std::size_t a = static_cast<std::size_t>(i);
            const std::size_t b = a + 1;

            const double ma = std::norm(x[a]); // squared magnitude (no sqrt needed)
            const double mb = std::norm(x[b]);

            // Swap if out of order by magnitude
            if (ma > mb) {
                std::swap(x[a], x[b]);
            }
        }
        // Implicit barrier at end of omp for ensures phase completion before next phase.
    }
}
